                  "text": "Bundeskanzler Merz telefoniert mit dem Kronprinzen und Premierminister von Saudi-Arabien, Mohammed bin Salman Al Saud",
                  "href": "https://www.bundesregierung.de/breg-de/aktuelles/bundeskanzler-merz-telefoniert-mit-dem-kronprinzen-und-premierminister-von-saudi-arabien-mohammed-bin-salman-al-saud-2456682"
