                  "text": "Bundeskanzler Merz empfängt den britischen Premierminister Burnham",
                  "href": "https://www.bundesregierung.de/breg-de/aktuelles/bundeskanzler-merz-empfaengt-den-britischen-premierminister-burnham-2455532"
